// First level of a factor of 64q words whose upper half is zero: reads x[0, 32q), words < 4P,
// and writes the first radix-4 group of both halves (twiddles 1, 1, r[1] and r[1], r[2], r[3]),
// f[0, 8q), values < 8P. f may be x's storage: each column is read before it is written.
// Reads 4 bytes past x[32q). x and f 32-byte aligned, q >= 1. w: broadcast twiddles r[1],
// r[2], r[3], each followed by its Shoup quotient.
inline void forward_radix8(Vec* f, std::size_t q, const std::uint32_t* x, const Vec* w) {
    Vec* b = f + 4 * q;
    Vec* const end = f + q;
    asm volatile(
        "vpbroadcastd %[P], %%ymm15\n\t"
        "vpbroadcastd %[P2], %%ymm14\n\t"
        ".p2align 5\n\t"
        "1:\n\t"
        "vmovdqa (%[x],%[h3]), %%ymm0\n\t"
        "vmovdqu 4(%[x],%[h3]), %%ymm1\n\t"
        "vmovdqa (%[x],%[h]), %%ymm2\n\t"
        "vmovdqa (%[x],%[h],2), %%ymm3\n\t"
        "vmovdqu 4(%[x],%[h],2), %%ymm4\n\t"
        "vmovdqa (%[x]), %%ymm5\n\t"
        "vpmuludq 32(%[w]), %%ymm0, %%ymm6\n\t"
        "vpmulld (%[w]), %%ymm0, %%ymm0\n\t"
        "vpmuludq 32(%[w]), %%ymm1, %%ymm1\n\t"
        "vpaddd %[P4], %%ymm2, %%ymm7\n\t"
        "vpaddd %%ymm14, %%ymm2, %%ymm8\n\t"
        "vpaddd (%[x],%[h3]), %%ymm2, %%ymm9\n\t"
        "vpsrlq $32, %%ymm6, %%ymm6\n\t"
        "vpmuludq 32(%[w]), %%ymm3, %%ymm10\n\t"
        "vpsubd (%[x],%[h3]), %%ymm7, %%ymm7\n\t"
        "vpblendd $170, %%ymm1, %%ymm6, %%ymm1\n\t"
        "vpmuludq 32(%[w]), %%ymm4, %%ymm4\n\t"
        "vpsrlq $32, %%ymm7, %%ymm6\n\t"
        "vpmuludq 32(%[w]), %%ymm7, %%ymm11\n\t"
        "vpmulld %%ymm15, %%ymm1, %%ymm1\n\t"
        "vpmuludq 32(%[w]), %%ymm6, %%ymm6\n\t"
        "vpaddd %[P4], %%ymm5, %%ymm12\n\t"
        "vpaddd %%ymm14, %%ymm5, %%ymm13\n\t"
        "vpsrlq $32, %%ymm10, %%ymm10\n\t"
        "vpmulld (%[w]), %%ymm3, %%ymm3\n\t"
        "vpsubd (%[x],%[h],2), %%ymm12, %%ymm12\n\t"
        "vpblendd $170, %%ymm4, %%ymm10, %%ymm4\n\t"
        "vpsrlq $32, %%ymm11, %%ymm11\n\t"
        "vpmulld (%[w]), %%ymm7, %%ymm7\n\t"
        "vpaddd (%[x],%[h],2), %%ymm5, %%ymm10\n\t"
        "vpsubd %%ymm1, %%ymm0, %%ymm1\n\t"
        "vpmulld %%ymm15, %%ymm4, %%ymm4\n\t"
        "vpblendd $170, %%ymm6, %%ymm11, %%ymm6\n\t"
        "vpsubd %[P4], %%ymm10, %%ymm11\n\t"
        "vpaddd %%ymm1, %%ymm2, %%ymm2\n\t"
        "vpsubd %%ymm1, %%ymm8, %%ymm1\n\t"
        "vpmulld %%ymm15, %%ymm6, %%ymm6\n\t"
        "vpsubd %[P4], %%ymm12, %%ymm8\n\t"
        "vpsrlq $32, %%ymm2, %%ymm0\n\t"
        "vpminud %%ymm11, %%ymm10, %%ymm11\n\t"
        "vpsubd %[P4], %%ymm9, %%ymm10\n\t"
        "vpminud %%ymm8, %%ymm12, %%ymm8\n\t"
        "vpmuludq 96(%[w]), %%ymm2, %%ymm12\n\t"
        "vpmuludq 96(%[w]), %%ymm0, %%ymm0\n\t"
        "vpsubd %%ymm4, %%ymm3, %%ymm4\n\t"
        "vpminud %%ymm10, %%ymm9, %%ymm10\n\t"
        "vpsrlq $32, %%ymm1, %%ymm9\n\t"
        "vpmuludq 160(%[w]), %%ymm1, %%ymm3\n\t"
        "vpmulld 64(%[w]), %%ymm2, %%ymm2\n\t"
        "vpaddd %%ymm4, %%ymm5, %%ymm5\n\t"
        "vpmuludq 160(%[w]), %%ymm9, %%ymm9\n\t"
        "vpmulld 128(%[w]), %%ymm1, %%ymm1\n\t"
        "vpsubd %%ymm4, %%ymm13, %%ymm4\n\t"
        "vpsubd %%ymm6, %%ymm7, %%ymm6\n\t"
        "vpsrlq $32, %%ymm12, %%ymm12\n\t"
        "vpaddd %[P4], %%ymm11, %%ymm7\n\t"
        "vpaddd %%ymm14, %%ymm8, %%ymm13\n\t"
        "vpaddd %%ymm10, %%ymm11, %%ymm11\n\t"
        "vpsrlq $32, %%ymm3, %%ymm3\n\t"
        "vpblendd $170, %%ymm0, %%ymm12, %%ymm0\n\t"
        "vpsubd %%ymm10, %%ymm7, %%ymm10\n\t"
        "vpaddd %%ymm6, %%ymm8, %%ymm8\n\t"
        "vmovdqa %%ymm11, (%[a])\n\t"
        "vpblendd $170, %%ymm9, %%ymm3, %%ymm9\n\t"
        "vpmulld %%ymm15, %%ymm0, %%ymm0\n\t"
        "vpaddd %%ymm14, %%ymm5, %%ymm3\n\t"
        "vpaddd %%ymm14, %%ymm4, %%ymm11\n\t"
        "vmovdqa %%ymm10, (%[a],%[h])\n\t"
        "vpmulld %%ymm15, %%ymm9, %%ymm9\n\t"
        "vpsubd %%ymm6, %%ymm13, %%ymm6\n\t"
        "vmovdqa %%ymm8, (%[a],%[h],2)\n\t"
        "vmovdqa %%ymm6, (%[a],%[h3])\n\t"
        "vpsubd %%ymm0, %%ymm2, %%ymm0\n\t"
        "vpsubd %%ymm9, %%ymm1, %%ymm9\n\t"
        "vpaddd %%ymm0, %%ymm5, %%ymm5\n\t"
        "vpsubd %%ymm0, %%ymm3, %%ymm0\n\t"
        "vpaddd %%ymm9, %%ymm4, %%ymm4\n\t"
        "vpsubd %%ymm9, %%ymm11, %%ymm9\n\t"
        "vmovdqa %%ymm5, (%[b])\n\t"
        "vmovdqa %%ymm0, (%[b],%[h])\n\t"
        "vmovdqa %%ymm4, (%[b],%[h],2)\n\t"
        "vmovdqa %%ymm9, (%[b],%[h3])\n\t"
        "add $32, %[x]\n\t"
        "add $32, %[a]\n\t"
        "add $32, %[b]\n\t"
        "cmp %[end], %[a]\n\t"
        "jne 1b\n\t"
        : [a] "+r"(f), [b] "+r"(b), [x] "+r"(x)
        : [end] "r"(end), [h] "r"(32 * q), [h3] "r"(96 * q), [w] "r"(w),
          [P] "m"(kP), [P2] "m"(k2P), [P4] "m"(k4P), [P8] "m"(k8P)
        : "xmm0", "xmm1", "xmm2", "xmm3", "xmm4", "xmm5", "xmm6", "xmm7", "xmm8", "xmm9", "xmm10", "xmm11", "xmm12", "xmm13", "xmm14", "xmm15", "memory", "cc");
}

